import {test,expect} from '@playwright/test';
import {openAdmittedReview} from '../tests/browser/keyboardAdmission';
for(const width of [320,390,768,1280])test(`${width}px permission retry retires between visible and enabled observation`,async({page})=>{
 await page.setViewportSize({width,height:844});
 await page.setContent('<style>body{font:200% sans-serif}button,input{font:inherit;min-height:44px;max-width:100%;box-sizing:border-box}</style><button>Retry permission check</button><form hidden><label>Invitation email<input type="email"></label></form>');
 await page.evaluate(()=>{document.documentElement.dataset.clicks='0';document.querySelector('button')!.addEventListener('click',()=>{document.documentElement.dataset.clicks=String(Number(document.documentElement.dataset.clicks)+1);});});
 const actual=page.getByRole('button',{name:'Retry permission check',exact:true}),field=page.getByLabel('Invitation email');
 let pressed=false,retired=false;
 const launcher=new Proxy(actual,{get(target,key){
  if(key==='isVisible')return async()=>{const visible=await target.isVisible();if(pressed&&visible&&!retired){retired=true;await page.evaluate(()=>{document.querySelector('button')!.remove();document.querySelector('form')!.hidden=false;});}return visible;};
  if(key==='press')return async(...args:Parameters<typeof actual.press>)=>{await target.press(...args);await expect(page.locator('html')).toHaveAttribute('data-clicks','1');pressed=true;};
  const value=Reflect.get(target,key);return typeof value==='function'?value.bind(target):value;
 }});
 await openAdmittedReview(launcher,field);
 await expect(field).toBeVisible();await field.fill('review@example.test');await expect(field).toHaveValue('review@example.test');
 await expect(page.locator('html')).toHaveAttribute('data-clicks','1');expect(retired).toBe(true);
 await page.screenshot({path:`work/invitation-readonly-bound-${width}.png`});
});
